        /// #1551: SQLite derives journal, WAL and SHM names from the path it
        /// opened, so two hard-linked names for one database break
        /// coordinated access and crash recovery. Every runtime constructor
        /// must refuse a multiply linked database typed, through either name,
        /// before any SQLite open or profile mutation touches either name.
        #[cfg(unix)]
        #[test]
        fn hard_linked_database_is_refused_before_open_mutates_either_name() {
            let dir = TempDir::new().unwrap();
            let first_dir = dir.path().join("first");
            let second_dir = dir.path().join("second");
            std::fs::create_dir_all(&first_dir).unwrap();
            std::fs::create_dir_all(&second_dir).unwrap();
            let original = first_dir.join("runtime.sqlite3");
            drop(SqliteRuntimeStore::new(&original).expect("create runtime database"));
            {
                // Canary: a refused open must not convert the journal to WAL.
                let conn = rusqlite::Connection::open(&original).unwrap();
                let mode: String = conn
                    .query_row("PRAGMA journal_mode=DELETE", [], |row| row.get(0))
                    .unwrap();
                assert_eq!(mode, "delete");
            }
            let linked = second_dir.join("runtime.sqlite3");
            std::fs::hard_link(&original, &linked).unwrap();

            let unrelated = dir.path().join("unrelated.sqlite3");
            drop(SqliteRuntimeStore::new(&unrelated).expect("a single-link database still opens"));

            let capture = |name: &Path| -> Vec<Option<Vec<u8>>> {
                ["", "-wal", "-shm", "-journal"]
                    .iter()
                    .map(|suffix| std::fs::read(format!("{}{suffix}", name.display())).ok())
                    .collect()
            };
            let before = (capture(&original), capture(&linked));
            for name in [&original, &linked] {
                let attempts = [
                    ("new", SqliteRuntimeStore::new(name).map(drop)),
                    (
                        "new_head_canonical",
                        SqliteRuntimeStore::new_head_canonical(name).map(drop),
                    ),
                    (
                        "open_existing_whole_blob",
                        SqliteRuntimeStore::open_existing_whole_blob(name).map(drop),
                    ),
                ];
                for (constructor, result) in attempts {
                    assert!(
                        matches!(result, Err(RuntimeStoreError::Unsupported(_))),
                        "{constructor} through {}: expected a typed Unsupported refusal, got {result:?}",
                        name.display()
                    );
                    assert_eq!(
                        (capture(&original), capture(&linked)),
                        before,
                        "{constructor} through {} changed a database, WAL, SHM or journal file",
                        name.display()
                    );
                }
            }
        }

        #[tokio::test]
        async fn external_activation_advances_only_representation_side_predecessor() {
            use meerkat_core::SessionStore as _;

            let tempdir = TempDir::new().unwrap();
            let session_store = Arc::new(
                meerkat_store::SqliteSessionStore::open(tempdir.path().join("sessions.sqlite3"))
                    .unwrap(),
            );
            let session = meerkat_core::Session::new();
            let root =
                meerkat_core::session_store::PreparedHeadCanonicalMutation::prepare_root(&session)
                    .unwrap();
            Arc::clone(&session_store)
                .as_incremental()
                .unwrap()
                .apply_prepared_head_canonical_mutation(&root)
                .await
                .unwrap();
            let activation = Arc::clone(&session_store)
                .as_incremental()
                .unwrap()
                .activate_head_canonical_store()
                .await
                .unwrap();
            let meerkat_core::HeadCanonicalStoreActivation::Activated(mut crossings) = activation
            else {
                panic!("SQLite store activation must apply");
            };
            let verified = match crossings.pop().unwrap() {
                meerkat_core::HeadCanonicalAuthorityCrossing::AlreadyCurrent(authority) => {
                    authority
                }
                other => panic!("expected already-current root proof, got {other:?}"),
            };

            let mut predecessor = verified.head().clone();
            assert_eq!(verified.head().version, 4);
            predecessor.version = 3;
            let inline_metadata = predecessor.materialized_metadata().unwrap();
            predecessor.message_row_prefix = None;
            predecessor.row_lineage_anchor = None;
            predecessor.graph_prefix = None;
            predecessor.realtime_event_prefix = None;
            predecessor.metadata_identity = None;
            predecessor.metadata = inline_metadata;
            // The representation-side predecessor is a persisted legacy head.
            // Round-tripping drops the sealed, non-serialized current metadata
            // projection that accompanied the verified successor in memory.
            let predecessor: meerkat_core::session_store::SessionHead =
                serde_json::from_slice(&serde_json::to_vec(&predecessor).unwrap()).unwrap();
            let predecessor_token = meerkat_core::session_head_cas_token(&predecessor).unwrap();
            let runtime_id = LogicalRuntimeId::for_session(&predecessor.id);
            let runtime_store =
                SqliteRuntimeStore::new_head_canonical(tempdir.path().join("runtime.sqlite3"))
                    .unwrap();
            let mut conn = open_head_canonical_runtime_connection(runtime_store.path()).unwrap();
            let tx = begin_runtime_transaction(&mut conn).unwrap();
            tx.execute(
                r"
                INSERT INTO runtime_session_authority (
                    runtime_id, authority_version, session_id, store_revision,
                    boundary_head_json, committed_head_token
                ) VALUES (?1, ?2, ?3, 7, ?4, ?5)
                ",
                params![
                    runtime_id_text(&runtime_id),
                    i64::from(HeadCanonicalStoreAuthority::VERSION),
                    predecessor.id.to_string(),
                    serde_json::to_vec(&predecessor).unwrap(),
                    predecessor_token,
                ],
            )
            .unwrap();
            tx.commit().unwrap();

            let outcome = runtime_store
                .activate_head_canonical_runtime_authority(verified.clone())
                .await
                .unwrap();
            assert!(matches!(
                outcome,
                HeadCanonicalRuntimeAuthorityActivation::RepresentationAdvanced(ref authority)
                    if authority.store_revision() == 8
                        && authority.committed_head_token() == verified.head_token()
            ));
            let current = runtime_store
                .load_session_boundary_authority(&runtime_id)
                .await
                .unwrap()
                .unwrap();
            assert_eq!(
                current.head_canonical().unwrap().committed_head_token(),
                verified.head_token()
            );
            assert_eq!(
                RuntimeStore::load_head_canonical_metadata(
                    &runtime_store,
                    current.head_canonical().unwrap(),
                )
                .await
                .unwrap(),
                verified.head().materialized_metadata().unwrap(),
                "separate-database runtime metadata must use its retained standalone owner",
            );
        }

        fn file_journal_mode(path: &Path) -> String {
            // A fresh connection, opened normally: journal mode is recorded
            // in the database header, so reading it back over a connection
            // the store did not configure is the only honest check. (A probe
            // that opens with `immutable=1` reports `delete` for every file,
            // WAL included, and can never answer this question.)
            let conn = meerkat_sqlite::open(path, meerkat_sqlite::ConnectionProfile::ReadOnly)
                .expect("read-only reopen");
            conn.pragma_query_value(None, "journal_mode", |row| row.get(0))
                .expect("journal_mode")
        }

        /// The durable-writer invariant, asserted through the constructor the
        /// production hosts actually call. A rollback-journal runtime
        /// database takes a database-wide EXCLUSIVE lock for every write,
        /// with no reader/writer separation, so any host with durable
        /// on-disk runtime state depends on this holding.
        #[test]
        fn production_runtime_store_open_leaves_the_database_in_wal() {
            let tempdir = TempDir::new().unwrap();
            let path = tempdir.path().join("runtime.sqlite3");
            let store = SqliteRuntimeStore::new(path.clone()).unwrap();
            assert_eq!(file_journal_mode(store.path()), "wal");

            // Head-canonical composition shares the same open path and owes
            // the same guarantee.
            let head_canonical_path = tempdir.path().join("head-canonical.sqlite3");
            let store = SqliteRuntimeStore::new_head_canonical(head_canonical_path).unwrap();
            assert_eq!(file_journal_mode(store.path()), "wal");
        }

        /// A host that already carries a rollback-journal runtime database
        /// converges on the ordinary open, with its rows intact: no operator
        /// step, no separate migration verb.
        #[test]
        fn existing_delete_mode_runtime_database_converts_on_open_with_content_intact() {
            let tempdir = TempDir::new().unwrap();
            let path = tempdir.path().join("runtime.sqlite3");
            {
                let conn = Connection::open(&path).unwrap();
                conn.execute_batch(
                    "CREATE TABLE host_marker (x INTEGER); INSERT INTO host_marker VALUES (7);",
                )
                .unwrap();
                let mode: String = conn
                    .pragma_query_value(None, "journal_mode", |row| row.get(0))
                    .unwrap();
                assert_eq!(mode, "delete", "fixture must start non-WAL");
            }

            let store = SqliteRuntimeStore::new(path.clone()).unwrap();
            assert_eq!(file_journal_mode(store.path()), "wal");

            let conn = Connection::open(&path).unwrap();
            let carried: i64 = conn
                .query_row("SELECT x FROM host_marker", [], |row| row.get(0))
                .unwrap();
            assert_eq!(carried, 7, "conversion must not disturb existing content");
        }

        #[tokio::test]
        async fn pending_terminal_owner_index_satisfies_store_contract() {
            let tempdir = tempfile::TempDir::new().unwrap();
            let store = SqliteRuntimeStore::new(tempdir.path().join("runtime.sqlite3")).unwrap();
            crate::store::assert_pending_terminal_owner_index_contract(&store).await;
        }

        #[tokio::test]
        async fn recovery_input_revision_rejects_a_phantom_insert_after_empty_observation() {
            let tempdir = tempfile::TempDir::new().unwrap();
            let store = SqliteRuntimeStore::new(tempdir.path().join("runtime.sqlite3")).unwrap();
            let runtime_id = LogicalRuntimeId::new("recovery-input-set-race");
            let observed = store
                .load_input_states_with_versions(&runtime_id)
                .await
                .unwrap();
            assert!(observed.exact_set_token().starts_with("sha256:"));
            let observed_revision = observed.input_set_revision();
            let observed_token = observed.exact_set_token().to_string();

            store
                .persist_input_state(
                    &runtime_id,
                    &InputStatePersistenceRecord::from_machine_snapshot(
                        StoredInputState::new_accepted(InputId::new()),
                    )
                    .unwrap(),
                )
                .await
                .unwrap();

            let mut conn = open_runtime_connection(store.path()).unwrap();
            let tx = begin_runtime_transaction(&mut conn).unwrap();
            let error = enforce_recovery_input_set_authority(
                &tx,
                &runtime_id,
                observed_revision,
                &observed_token,
            )
            .unwrap_err();
            assert!(matches!(
                error,
                RuntimeStoreError::RecoveryInputSetConflict {
                    runtime_id: conflicted
                } if conflicted == runtime_id.to_string()
            ));
        }

        #[tokio::test]
        async fn recovery_input_authority_rejects_token_mismatch_at_same_revision() {
            let tempdir = tempfile::TempDir::new().unwrap();
            let store = SqliteRuntimeStore::new(tempdir.path().join("runtime.sqlite3")).unwrap();
            let runtime_id = LogicalRuntimeId::new("recovery-input-set-token-mismatch");
            let observed = store
                .load_input_states_with_versions(&runtime_id)
                .await
                .unwrap();

            let mut conn = open_runtime_connection(store.path()).unwrap();
            let tx = begin_runtime_transaction(&mut conn).unwrap();
            let error = enforce_recovery_input_set_authority(
                &tx,
                &runtime_id,
                observed.input_set_revision(),
                "sha256:wrong-input-set-token",
            )
            .unwrap_err();
            assert!(matches!(
                error,
                RuntimeStoreError::RecoveryInputSetConflict {
                    runtime_id: conflicted
                } if conflicted == runtime_id.to_string()
            ));
        }

        #[test]
        fn runtime_v2_migrates_published_v1_rows_to_current_schema() {
            let mut conn = Connection::open_in_memory().unwrap();
            let tx = conn.transaction().unwrap();
            migration_0001_runtime_schema(&tx).unwrap();
            // This crate's own copy of meerkat-core's synthetic 0.8.10
            // recovery-migration session (so the test builds from the
            // published package), pinned to the original's provenance digest.
            let released_session =
                include_bytes!("../../tests/fixtures/v0_8_10_recovery_migration_session.json");
            {
                use sha2::Digest as _;
                assert_eq!(
                    format!("{:x}", sha2::Sha256::digest(released_session)),
                    "3a1ba2e6ff8889c913dc0801c540c81a38bae7b54269259d8e370d1275a12c8a",
                    "the copy differs from meerkat-core's 0.8.10 recovery-migration fixture"
                );
            }
            let imported = meerkat_core::import_released_0810_session(released_session).unwrap();
            let runtime_id = LogicalRuntimeId::for_session(imported.receipt().session_id());
            let expected_session = imported.session().clone();
            let input_id = InputId::new();
            let (mut stored, _) =
                crate::store::pending_terminal_owner_fixture(input_id.clone(), false);
            stored.state.persisted_input = Some(crate::input::Input::Prompt(
                crate::input::PromptInput::new("pending directed payload", None),
            ));
            stored.seed.phase = crate::input_state::InputLifecycleState::Consumed;
            stored.seed.terminal_outcome = Some(crate::input_state::InputTerminalOutcome::Consumed);
            stored.seed.recovery_lane = None;
            let as_released_v4 = |stored: &StoredInputState| {
                let mut encoded = serde_json::to_value(stored).unwrap();
                encoded["stored_input_state_version"] = serde_json::json!(4);
                let object = encoded.as_object_mut().unwrap();
                object.remove("directed_run_started_attribution");
                object.remove("terminal_completion");
                object.remove("terminal_completion_unavailable");
                encoded
            };
            let pending_json = as_released_v4(&stored);
            let state_json = serde_json::to_vec(&pending_json).unwrap();
            tx.execute(
                r"
                INSERT INTO runtime_input_states (runtime_id, input_id, state_json)
                VALUES (?1, ?2, ?3)
                ",
                params![
                    runtime_id_text(&runtime_id),
                    input_id.0.to_string(),
                    state_json
                ],
            )
            .unwrap();
            let insert_released_context_row =
                |tx: &rusqlite::Transaction<'_>,
                 runtime_id: &LogicalRuntimeId,
                 input: crate::input::Input,
                 semantics: crate::ingress_types::RuntimeInputSemantics,
                 context_key: &str,
                 context_text: &str| {
                    let input_id = input.id().clone();
                    let mut stored = StoredInputState::new_accepted(input_id.clone());
                    stored.state.runtime_semantics = Some(semantics);
                    stored.state.persisted_input = Some(input);
                    let mut encoded = as_released_v4(&stored);
                    encoded["persisted_input"]["context_append"] = serde_json::json!({
                        "key": context_key,
                        "content": {
                            "type": "text",
                            "text": context_text,
                        },
                    });
                    let bytes = serde_json::to_vec(&encoded).unwrap();
                    tx.execute(
                        "INSERT INTO runtime_input_states (runtime_id, input_id, state_json)
                         VALUES (?1, ?2, ?3)",
                        params![runtime_id_text(runtime_id), input_id.0.to_string(), bytes],
                    )
                    .unwrap();
                    input_id
                };
            let steer_continuation =
                crate::input::Input::Continuation(crate::input::ContinuationInput {
                    header: crate::input::InputHeader {
                        ingress_context: None,
                        retained_resume: None,
                        authority_association: None,
                        id: InputId::new(),
                        timestamp: chrono::Utc::now(),
                        source: crate::input::InputOrigin::System,
                        durability: crate::input::InputDurability::Durable,
                        visibility: crate::input::InputVisibility::default(),
                        idempotency_key: None,
                        supersession_key: None,
                        correlation_id: None,
                    },
                    reason: "released active steer".to_string(),
                    continuation_kind: crate::input::ContinuationKind::Ordinary,
                    handling_mode: meerkat_core::types::HandlingMode::Steer,
                    request_id: None,
                    turn_tool_overlay: None,
                    turn_append: None,
                });
            let steer_semantics = crate::ingress_types::RuntimeInputSemantics {
                boundary: RunApplyBoundary::RunCheckpoint,
                execution_kind: meerkat_core::lifecycle::RuntimeExecutionKind::ResumePending,
                execution_handling_mode: None,
                peer_response_terminal_apply_intent: None,
                live_interrupt_required: true,
                live_boundary_delivery: None,
            };
            let released_steer_id = insert_released_context_row(
                &tx,
                &runtime_id,
                steer_continuation,
                steer_semantics,
                "released:steer:one",
                "  exact steer bytes  ",
            );
            let instruction_continuation =
                crate::input::Input::Continuation(crate::input::ContinuationInput {
                    header: crate::input::InputHeader {
                        ingress_context: None,
                        retained_resume: None,
                        authority_association: None,
                        id: InputId::new(),
                        timestamp: chrono::Utc::now(),
                        source: crate::input::InputOrigin::System,
                        durability: crate::input::InputDurability::Durable,
                        visibility: crate::input::InputVisibility::default(),
                        idempotency_key: None,
                        supersession_key: None,
                        correlation_id: None,
                    },
                    reason: "released instruction continuation".to_string(),
                    continuation_kind: crate::input::ContinuationKind::WorkgraphAttention,
                    handling_mode: meerkat_core::types::HandlingMode::Queue,
                    request_id: None,
                    turn_tool_overlay: None,
                    turn_append: None,
                });
            let instruction_semantics = crate::ingress_types::RuntimeInputSemantics {
                boundary: RunApplyBoundary::RunStart,
                execution_kind: meerkat_core::lifecycle::RuntimeExecutionKind::ContentTurn,
                execution_handling_mode: None,
                peer_response_terminal_apply_intent: None,
                live_interrupt_required: false,
                live_boundary_delivery: None,
            };
            let released_instruction_id = insert_released_context_row(
                &tx,
                &runtime_id,
                instruction_continuation,
                instruction_semantics,
                "released:instruction:one",
                "  legacy instruction  ",
            );
            let terminal_input = crate::input::Input::Prompt(crate::input::PromptInput::new(
                "released terminal payload",
                None,
            ));
            let terminal_input_id = terminal_input.id().clone();
            let mut terminal = StoredInputState::new_accepted(terminal_input_id.clone());
            terminal.state.persisted_input = Some(terminal_input);
            terminal.seed.phase = crate::input_state::InputLifecycleState::Consumed;
            terminal.seed.terminal_outcome =
                Some(crate::input_state::InputTerminalOutcome::Consumed);
            terminal.seed.recovery_lane = None;
            let terminal_json = as_released_v4(&terminal);
            let terminal_state_json = serde_json::to_vec(&terminal_json).unwrap();
            tx.execute(
                r"
                INSERT INTO runtime_input_states (runtime_id, input_id, state_json)
                VALUES (?1, ?2, ?3)
                ",
                params![
                    runtime_id_text(&runtime_id),
                    terminal_input_id.0.to_string(),
                    terminal_state_json
                ],
            )
            .unwrap();
            tx.execute(
                r#"
                INSERT INTO runtime_input_states (runtime_id, input_id, state_json)
                VALUES (
                    'unindexable-runtime',
                    'duplicate-key-row',
                    '{"idempotency_key":"first-key","idempotency_key":"second-key"}'
                )
                "#,
                [],
            )
            .unwrap();
            tx.execute(
                r"
                INSERT INTO runtime_session_snapshots (runtime_id, session_snapshot)
                VALUES (?1, ?2)
                ",
                params![runtime_id_text(&runtime_id), released_session.as_slice()],
            )
            .unwrap();
            let released_receipt = RunBoundaryReceipt {
                run_id: RunId::new(),
                boundary: RunApplyBoundary::Immediate,
                contributing_input_ids: vec![input_id.clone()],
                conversation_digest: None,
                message_count: expected_session.messages().len(),
                sequence: 7,
                owner_contributions: Vec::new(),
            };
            let released_receipt_json = serde_json::to_vec(&released_receipt).unwrap();
            tx.execute(
                r"
                INSERT INTO runtime_boundary_receipts (
                    runtime_id, run_id, sequence, receipt_json
                ) VALUES (?1, ?2, ?3, ?4)
                ",
                params![
                    runtime_id_text(&runtime_id),
                    released_receipt.run_id.0.to_string(),
                    encode_receipt_sequence(released_receipt.sequence),
                    &released_receipt_json,
                ],
            )
            .unwrap();

            // The ordinary v1 -> v2 upgrade always runs against a file that
            // already carries this domain's ledger row: `apply_domain_migrations`
            // initializes a fresh domain instead of migrating it, and refuses an
            // unledgered one that owns objects. The row is what tells the
            // released-row importers they are upgrading a realm this lineage
            // wrote rather than rescuing one from before the durable-state floor
            // (see `pre_0_8_10_rescue_in_progress`), so a test that omits it is
            // exercising the other path under this one's name.
            tx.execute_batch(
                "CREATE TABLE IF NOT EXISTS main.meerkat_schema (
                     domain TEXT PRIMARY KEY,
                     version INTEGER NOT NULL
                 )",
            )
            .unwrap();
            tx.execute(
                "INSERT INTO main.meerkat_schema (domain, version) VALUES (?1, 1)",
                params![RUNTIME_STORE_DOMAIN.name],
            )
            .unwrap();

            migration_0002_current_runtime_schema(&tx).unwrap();

            let (authority_session_id, store_revision, blob_sha256, body) = tx
                .query_row(
                    r"
                    SELECT authority.session_id, authority.store_revision,
                           authority.blob_sha256, body.session_snapshot
                    FROM runtime_whole_blob_authority AS authority
                    JOIN runtime_whole_blob_bodies AS body
                      ON body.blob_sha256 = authority.blob_sha256
                    WHERE authority.runtime_id = ?1
                    ",
                    params![runtime_id_text(&runtime_id)],
                    |row| {
                        Ok((
                            row.get::<_, String>(0)?,
                            row.get::<_, i64>(1)?,
                            row.get::<_, String>(2)?,
                            row.get::<_, JsonColumnBytes>(3)?.into_bytes(),
                        ))
                    },
                )
                .unwrap();
            assert_eq!(authority_session_id, expected_session.id().to_string());
            assert_eq!(store_revision, 1);
            assert_eq!(blob_sha256, whole_blob_body_sha256(&body));
            assert_eq!(body, expected_session.to_persisted_bytes().unwrap());
            let decoded = meerkat_core::Session::from_persisted_bytes(&body).unwrap();
            assert_eq!(decoded.id(), expected_session.id());
            assert_eq!(decoded.messages(), expected_session.messages());
            assert_eq!(
                tx.query_row(
                    r"
                    SELECT receipt_sha256
                    FROM runtime_released_0810_boundary_receipts
                    WHERE runtime_id = ?1 AND run_id = ?2 AND sequence = ?3
                    ",
                    params![
                        runtime_id_text(&runtime_id),
                        released_receipt.run_id.0.to_string(),
                        encode_receipt_sequence(released_receipt.sequence),
                    ],
                    |row| row.get::<_, String>(0),
                )
                .unwrap(),
                input_row_version_digest(&released_receipt_json),
                "v1 -> v2 activation must bind exact released receipt bytes in its one-time allowlist"
            );

            let catalog = load_runtime_session_catalog_entry_in_txn(&tx, &runtime_id)
                .unwrap()
                .expect("migrated WholeBlob session is cataloged");
            assert_eq!(catalog.session_id(), expected_session.id());
            assert_eq!(
                catalog.persistence_profile(),
                RuntimeSessionPersistenceProfile::WholeBlobV1
            );
            assert_eq!(catalog.created_at(), expected_session.created_at());
            assert_eq!(catalog.updated_at(), expected_session.updated_at());
            assert_eq!(catalog.message_count(), expected_session.messages().len());
            assert_eq!(catalog.total_tokens(), expected_session.total_tokens());
            assert_eq!(catalog.runtime_state(), None);
            assert_eq!(
                list_runtime_session_catalog_entries_in_conn(
                    &tx,
                    meerkat_core::SessionFilter::default(),
                )
                .unwrap(),
                vec![catalog],
                "migrated WholeBlob state must be immediately listable"
            );

            assert_eq!(
                tx.query_row(
                    r"
                    SELECT owner_input_id
                    FROM runtime_pending_terminal_owners
                    WHERE runtime_id = ?1
                    ",
                    params![runtime_id_text(&runtime_id)],
                    |row| row.get::<_, String>(0),
                )
                .unwrap(),
                input_id.0.to_string()
            );
            let migrated_pending = tx
                .query_row(
                    "SELECT state_json
                     FROM runtime_input_states
                     WHERE runtime_id = ?1 AND input_id = ?2",
                    params![runtime_id_text(&runtime_id), input_id.0.to_string()],
                    |row| row.get::<_, JsonColumnBytes>(0),
                )
                .map(JsonColumnBytes::into_bytes)
                .map(|bytes| deserialize_persisted_input_state(&bytes))
                .unwrap()
                .unwrap();
            assert!(
                migrated_pending.state.persisted_input.is_some(),
                "pending terminal outbox retains its exact retry payload during activation"
            );
            let migrated_terminal = tx
                .query_row(
                    "SELECT state_json
                     FROM runtime_input_states
                     WHERE runtime_id = ?1 AND input_id = ?2",
                    params![
                        runtime_id_text(&runtime_id),
                        terminal_input_id.0.to_string()
                    ],
                    |row| row.get::<_, JsonColumnBytes>(0),
                )
                .map(JsonColumnBytes::into_bytes)
                .map(|bytes| deserialize_persisted_input_state(&bytes))
                .unwrap()
                .unwrap();
            assert_eq!(
                migrated_terminal.seed.phase,
                crate::input_state::InputLifecycleState::Consumed
            );
            assert_eq!(
                migrated_terminal.seed.terminal_outcome,
                Some(crate::input_state::InputTerminalOutcome::Consumed)
            );
            assert!(
                migrated_terminal.state.persisted_input.is_none(),
                "exact v1 -> v2 activation retires closed terminal payload bytes"
            );
            for (input_id, expected_role, expected_text, expected_key) in [
                (
                    released_steer_id,
                    meerkat_core::lifecycle::run_primitive::ConversationAppendRole::User,
                    "  exact steer bytes  ",
                    None,
                ),
                (
                    released_instruction_id,
                    meerkat_core::lifecycle::run_primitive::ConversationAppendRole::System,
                    "[Runtime System Context]\nsource: released:instruction:one\n\nlegacy instruction",
                    Some("released:instruction:one"),
                ),
            ] {
                let (bytes, migrated) = tx
                    .query_row(
                        "SELECT state_json
                         FROM runtime_input_states
                         WHERE runtime_id = ?1 AND input_id = ?2",
                        params![runtime_id_text(&runtime_id), input_id.0.to_string()],
                        |row| row.get::<_, JsonColumnBytes>(0),
                    )
                    .map(JsonColumnBytes::into_bytes)
                    .map(|bytes| {
                        let migrated = deserialize_persisted_input_state(&bytes).unwrap();
                        (bytes, migrated)
                    })
                    .unwrap();
                assert!(
                    !String::from_utf8_lossy(&bytes).contains("context_append"),
                    "current row must not retain the released sidecar field"
                );
                let Some(crate::input::Input::Continuation(continuation)) =
                    migrated.state.persisted_input
                else {
                    panic!("migrated context row must retain its continuation input");
                };
                let append = continuation
                    .turn_append
                    .expect("released context must become an ordinary turn append");
                assert_eq!(append.role, expected_role);
                assert_eq!(append.content.render_text(), expected_text);
                assert_eq!(
                    append
                        .identity
                        .as_ref()
                        .and_then(|identity| identity.source.as_deref()),
                    expected_key
                );
                assert_eq!(
                    append
                        .identity
                        .as_ref()
                        .and_then(|identity| identity.idempotency_key.as_deref()),
                    expected_key
                );
            }
            assert_eq!(
                tx.query_row(
                    r"
                    SELECT revision
                    FROM runtime_input_set_revisions
                    WHERE runtime_id = ?1
                    ",
                    params![runtime_id_text(&runtime_id)],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
                1,
                "published v1 input rows must receive one exact initial set revision"
            );
            assert_eq!(
                tx.query_row(
                    r"
                    SELECT reason
                    FROM runtime_input_idempotency_unindexable_rows
                    WHERE runtime_id = 'unindexable-runtime'
                      AND input_id = 'duplicate-key-row'
                    ",
                    [],
                    |row| row.get::<_, String>(0),
                )
                .unwrap(),
                "idempotency_key appears more than once"
            );
            assert_eq!(
                tx.query_row(
                    "SELECT runtime_id FROM runtime_head_canonical_activation_queue",
                    [],
                    |row| row.get::<_, String>(0),
                )
                .unwrap(),
                runtime_id_text(&runtime_id)
            );
            assert!(
                !LOAD_HEAD_CANONICAL_ACTIVATION_CANDIDATES_SQL
                    .contains("runtime_session_snapshots"),
                "ordinary reopen must not rescan retained whole-BLOB history"
            );
        }

        use crate::identifiers::LogicalRuntimeId;
        use crate::runtime_state::RuntimeState;
        use crate::traits::RuntimeDriver as _;
        use meerkat_core::lifecycle::core_executor::BoundSessionCommit;
        use meerkat_core::lifecycle::run_primitive::RunApplyBoundary;
        use meerkat_core::lifecycle::{InputId, RunBoundaryReceipt, RunId};
        use meerkat_core::session_store::{
            IncrementalSessionStore as _, PreparedHeadCanonicalMutation, SessionStore as _,
        };
        use meerkat_core::types::{
            AssistantBlock, BlockAssistantMessage, Message, StopReason, UserMessage,
        };
        use meerkat_core::{Session, TranscriptRewriteReason, TranscriptRewriteSelection};
        use meerkat_store::SqliteSessionStore;

        fn temp_store() -> (TempDir, SqliteRuntimeStore) {
            let dir = TempDir::new().unwrap();
            let path = dir.path().join("sessions.sqlite3");
            let store = SqliteRuntimeStore::new(path).unwrap();
            (dir, store)
        }

        fn raw_fixture_row(path: &Path, table: &str, column: &str, runtime_id: &str) -> Vec<u8> {
            let conn = Connection::open(path).unwrap();
            conn.query_row(
                &format!("SELECT {column} FROM {table} WHERE runtime_id = ?1"),
                params![runtime_id],
                |row| Ok(row.get::<_, JsonColumnBytes>(0)?.into_bytes()),
            )
            .unwrap()
        }

        fn runtime_id() -> LogicalRuntimeId {
            LogicalRuntimeId("runtime-1".to_string())
        }

        fn lifecycle_commit(
            runtime_id: &LogicalRuntimeId,
            state: RuntimeState,
            fence_token: u64,
            runtime_generation: u64,
        ) -> MachineLifecycleCommit {
            MachineLifecycleCommit::new_with_binding(
                state,
                crate::store::MachineLifecycleBindingFacts::new(
                    Some(runtime_id.0.clone()),
                    Some(fence_token),
                    Some(runtime_generation),
                    Some(format!("epoch-{runtime_generation}")),
                ),
                crate::store::SupervisorAuthoritySnapshot::UnboundNoReceipt,
            )
        }

        struct AppliedWriteFence;

        impl RuntimeStoreWriteFence for AppliedWriteFence {
            fn execute_if_current(
                &self,
                operation: Box<dyn FnOnce() -> Result<(), RuntimeStoreError> + '_>,
            ) -> Result<RuntimeStoreWriteFenceOutcome, RuntimeStoreError> {
                operation()?;
                Ok(RuntimeStoreWriteFenceOutcome::Applied)
            }
        }

        #[derive(Clone, Copy)]
        enum SessionBoundaryFenceDecision {
            Applied,
            Conflict,
            Backoff,
        }

        struct SqliteSessionBoundaryFence {
            path: PathBuf,
            runtime_id: LogicalRuntimeId,
            visibility_table: &'static str,
            expected_visible_rows: i64,
            decision: SessionBoundaryFenceDecision,
        }

        impl RuntimeStoreWriteFence for SqliteSessionBoundaryFence {
            fn execute_if_current(
                &self,
                operation: Box<dyn FnOnce() -> Result<(), RuntimeStoreError> + '_>,
            ) -> Result<RuntimeStoreWriteFenceOutcome, RuntimeStoreError> {
                let conn = Connection::open(&self.path).unwrap();
                let visible_rows = conn
                    .query_row(
                        &format!(
                            "SELECT COUNT(*) FROM {} WHERE runtime_id = ?1",
                            self.visibility_table
                        ),
                        params![runtime_id_text(&self.runtime_id)],
                        |row| row.get::<_, i64>(0),
                    )
                    .unwrap();
                assert_eq!(
                    visible_rows, self.expected_visible_rows,
                    "session write fence must execute before the target transaction is visible"
                );
                match self.decision {
                    SessionBoundaryFenceDecision::Applied => {
                        operation()?;
                        Ok(RuntimeStoreWriteFenceOutcome::Applied)
                    }
                    SessionBoundaryFenceDecision::Conflict => {
                        Ok(RuntimeStoreWriteFenceOutcome::Conflict {
                            reason: "superseded identity generation".to_string(),
                        })
                    }
                    SessionBoundaryFenceDecision::Backoff => {
                        Ok(RuntimeStoreWriteFenceOutcome::Backoff {
                            reason: "identity authority busy".to_string(),
                        })
                    }
                }
            }
        }

        fn input_state() -> InputStatePersistenceRecord {
            InputStatePersistenceRecord::from_machine_snapshot(StoredInputState::new_accepted(
                InputId::new(),
            ))
            .expect("accepted test input state seed must be machine-authorized")
        }

        #[tokio::test]
        async fn fenced_session_boundary_is_decided_before_target_transaction_commit() {
            let (dir, store) = temp_store();
            let session = session_with_user("fenced activation");
            let runtime_id = LogicalRuntimeId::for_session(session.id());
            let request = || {
                PreparedRuntimeSessionCommit::snapshot_only(
                    BoundSessionCommit::sealed(Arc::new(session.clone())).unwrap(),
                )
            };
            let fence = |decision| {
                Arc::new(SqliteSessionBoundaryFence {
                    path: dir.path().join("sessions.sqlite3"),
                    runtime_id: runtime_id.clone(),
                    visibility_table: "runtime_whole_blob_authority",
                    expected_visible_rows: 0,
                    decision,
                }) as Arc<dyn RuntimeStoreWriteFence>
            };

            let conflict = RuntimeStore::commit_prepared_session_boundary_with_fence(
                &store,
                &runtime_id,
                request(),
                fence(SessionBoundaryFenceDecision::Conflict),
            )
            .await
            .unwrap();
            assert!(matches!(
                conflict,
                crate::store::FencedPreparedRuntimeSessionCommitOutcome::FenceConflict { .. }
            ));
            assert!(
                store
                    .load_session_snapshot(&runtime_id)
                    .await
                    .unwrap()
                    .is_none()
            );

            let backoff = RuntimeStore::commit_prepared_session_boundary_with_fence(
                &store,
                &runtime_id,
                request(),
                fence(SessionBoundaryFenceDecision::Backoff),
            )
            .await
            .unwrap();
            assert!(matches!(
                backoff,
                crate::store::FencedPreparedRuntimeSessionCommitOutcome::FenceBackoff { .. }
            ));
            assert!(
                store
                    .load_session_snapshot(&runtime_id)
                    .await
                    .unwrap()
                    .is_none()
            );

            let applied = RuntimeStore::commit_prepared_session_boundary_with_fence(
                &store,
                &runtime_id,
                request(),
                fence(SessionBoundaryFenceDecision::Applied),
            )
            .await
            .unwrap();
            assert!(matches!(
                applied,
                crate::store::FencedPreparedRuntimeSessionCommitOutcome::Applied(_)
            ));
            let committed = store
                .load_session_snapshot(&runtime_id)
                .await
                .unwrap()
                .expect("applied fence commits target snapshot");
            let committed: Session = serde_json::from_slice(committed.as_ref().as_slice()).unwrap();
            assert_eq!(committed.messages(), session.messages());

            for decision in [
                SessionBoundaryFenceDecision::Conflict,
                SessionBoundaryFenceDecision::Backoff,
            ] {
                let outcome = RuntimeStore::commit_prepared_session_boundary_with_fence(
                    &store,
                    &runtime_id,
                    request(),
                    Arc::new(SqliteSessionBoundaryFence {
                        path: dir.path().join("sessions.sqlite3"),
                        runtime_id: runtime_id.clone(),
                        visibility_table: "runtime_whole_blob_authority",
                        expected_visible_rows: 1,
                        decision,
                    }),
                )
                .await
                .unwrap();
                assert!(matches!(
                    (decision, outcome),
                    (
                        SessionBoundaryFenceDecision::Conflict,
                        crate::store::FencedPreparedRuntimeSessionCommitOutcome::FenceConflict { .. }
                    ) | (
                        SessionBoundaryFenceDecision::Backoff,
                        crate::store::FencedPreparedRuntimeSessionCommitOutcome::FenceBackoff { .. }
                    )
                ));
                let current = store
                    .load_session_snapshot(&runtime_id)
                    .await
                    .unwrap()
                    .expect("refused exact retry preserves committed snapshot");
                let current: Session = serde_json::from_slice(current.as_ref().as_slice()).unwrap();
                assert_eq!(current.messages(), session.messages());
            }
        }

        #[tokio::test]
        async fn head_canonical_metadata_read_preserves_compact_authority_and_refuses_stale_identity()
         {
            let dir = TempDir::new().unwrap();
            let path = dir.path().join("metadata.sqlite3");
            let store = SqliteRuntimeStore::new_head_canonical(&path).unwrap();
            let mut session = session_with_user("human intent");
            session.set_metadata("host_metadata", serde_json::json!("exact metadata"));
            let runtime_id = LogicalRuntimeId::for_session(session.id());
            let mutation = PreparedHeadCanonicalMutation::prepare(&session, None).unwrap();
            let request = PreparedRuntimeSessionCommit::snapshot_only(
                BoundSessionCommit::head_canonical_from_session(&session, mutation).unwrap(),
            );
            RuntimeStore::commit_prepared_session_boundary(&store, &runtime_id, request)
                .await
                .unwrap();
            let authority = RuntimeStore::load_session_boundary_authority(&store, &runtime_id)
                .await
                .unwrap()
                .unwrap();
            let head = authority.head_canonical().unwrap();
            assert!(head.boundary_head().metadata_projection().is_none());
            let metadata = RuntimeStore::load_head_canonical_metadata(&store, head)
                .await
                .unwrap();
            assert_eq!(
                metadata.get("host_metadata"),
                Some(&serde_json::json!("exact metadata"))
            );
            let polled = RuntimeStore::load_session_boundary_authority(&store, &runtime_id)
                .await
                .unwrap()
                .unwrap();
            assert!(
                polled
                    .head_canonical()
                    .unwrap()
                    .boundary_head()
                    .metadata_projection()
                    .is_none()
            );

            let wrong_revision = HeadCanonicalStoreAuthority::issued(
                head.session_id().clone(),
                head.store_revision() + 1,
                head.boundary_head().clone(),
                head.committed_head_token().to_string(),
            )
            .unwrap();
            assert!(matches!(
                RuntimeStore::load_head_canonical_metadata(&store, &wrong_revision).await,
                Err(RuntimeStoreError::SessionPersistenceAuthorityConflict { .. }),
            ));
            let conn = open_runtime_connection(&path).unwrap();
            conn.execute(
                "DELETE FROM session_head_metadata_refs WHERE session_id = ?1 AND owner = 'runtime_boundary'",
                [session.id().to_string()],
            ).unwrap();
            assert!(
                matches!(
                    RuntimeStore::load_head_canonical_metadata(&store, head).await,
                    Err(RuntimeStoreError::ReadFailed(_)),
                ),
                "missing exact metadata owner must not fall back to the latest physical head"
            );
        }

        /// A metadata observer that read the authority before a successor
        /// boundary committed must not turn that commit into an authority
        /// conflict: the exact-authority read refuses the stale identity (its
        /// contract), while the current read observes authority and metadata
        /// in one snapshot and returns the successor's metadata.
        #[tokio::test]
        async fn current_head_canonical_metadata_read_spans_a_successor_commit() {
            let dir = TempDir::new().unwrap();
            let path = dir.path().join("current-metadata.sqlite3");
            let store = SqliteRuntimeStore::new_head_canonical(&path).unwrap();
            let physical_store = SqliteSessionStore::open(path.clone()).unwrap();
            let mut session = session_with_user("first intent");
            session.set_metadata("host_metadata", serde_json::json!("first"));
            let session_id = session.id().clone();
            let runtime_id = LogicalRuntimeId::for_session(&session_id);
            let mutation = PreparedHeadCanonicalMutation::prepare(&session, None).unwrap();
            RuntimeStore::commit_prepared_session_boundary(
                &store,
                &runtime_id,
                PreparedRuntimeSessionCommit::snapshot_only(
                    BoundSessionCommit::head_canonical_from_session(&session, mutation).unwrap(),
                ),
            )
            .await
            .unwrap();
            let observed = RuntimeStore::load_session_boundary_authority(&store, &runtime_id)
                .await
                .unwrap()
                .unwrap()
                .head_canonical()
                .expect("first HeadCanonical authority")
                .clone();

            let observed_head = physical_store
                .load_head(&session_id)
                .await
                .unwrap()
                .expect("committed physical head");
            let mut successor = physical_store
                .load(&session_id)
                .await
                .unwrap()
                .expect("committed physical session");
            successor.push(Message::User(UserMessage::text(
                "second intent".to_string(),
            )));
            successor.set_metadata("host_metadata", serde_json::json!("second"));
            let successor_mutation =
                PreparedHeadCanonicalMutation::prepare(&successor, Some(observed_head)).unwrap();
            RuntimeStore::commit_prepared_session_boundary(
                &store,
                &runtime_id,
                PreparedRuntimeSessionCommit::snapshot_only(
                    BoundSessionCommit::head_canonical_from_session(&successor, successor_mutation)
                        .unwrap(),
                ),
            )
            .await
            .unwrap();

            assert!(
                matches!(
                    RuntimeStore::load_head_canonical_metadata(&store, &observed).await,
                    Err(RuntimeStoreError::SessionPersistenceAuthorityConflict { .. }),
                ),
                "the exact read still refuses the superseded authority"
            );
            let current = RuntimeStore::load_current_head_canonical_metadata(&store, &runtime_id)
                .await
                .unwrap()
                .expect("a HeadCanonical authority is current");
            assert_eq!(
                current.get("host_metadata"),
                Some(&serde_json::json!("second")),
                "the current read returns the successor boundary's metadata"
            );
            let absent = LogicalRuntimeId::for_session(&meerkat_core::types::SessionId::new());
            assert!(
                RuntimeStore::load_current_head_canonical_metadata(&store, &absent)
                    .await
                    .unwrap()
                    .is_none()
            );
        }

